    if(!join_)return "CancelButton";if(input.key==VK_ESCAPE && !screen_.popupOpen()){join_->cancel();return "CancelButton";}try{join_->poll();updateMapCheck();if(handoffEnabled_ && join_->state()==LanJoinState::Lobby && join_->loadPhase()==LanLoadPhase::Lobby && verifiedMapCheck_ && verifiedMap_ && verifiedMapInfo_ && join_->reportMapReady(*verifiedMapCheck_))join_->enableLoadingProtocol();if(handoffEnabled_ && join_->state()==LanJoinState::Lobby && join_->loadPhase()==LanLoadPhase::Loading){if(verifiedMap_ && verifiedMapInfo_ && verifiedMapCheck_ && expectedMap_ && join_->randomSeed() && join_->localPlayerId())return "PrepareGame";error_="房间加载配置不完整。";join_->cancel();}}catch(const std::exception& e){error_=e.what();}auto bounds=screen_.bounds("TeamSetupContainer");if(!screen_.popupOpen() && input.wheel && input.x>=bounds.x && input.y>=bounds.y && input.x<bounds.x+bounds.w && input.y<bounds.y+bounds.h){float height=screen_.bounds(prefix(0)+"/PlayerSlot").h;unsigned capacity=height>0?std::min(16u,std::max(1u,unsigned(std::floor((bounds.h-.02f)/height)))):1;auto maximum=join_->slots().size()>capacity?join_->slots().size()-capacity:0;scroll_=size_t(std::clamp<long long>(static_cast<long long>(scroll_)-input.wheel,0,static_cast<long long>(maximum)));}auto enabled=updateSlots();auto edit=screen_.bounds("ChatEditBox"),history=screen_.bounds("ChatTextArea");if(!screen_.popupOpen() && input.pressed)chatFocus_=inRect(edit,input.x,input.y) && inRect(edit,input.startX,input.startY);if(!screen_.popupOpen() && input.key==VK_TAB)chatFocus_=!chatFocus_;auto state=join_->state();if(!screen_.popupOpen() && chatFocus_ && state==LanJoinState::Lobby){for(wchar_t c:characters){if(c==8){chatHighSurrogate_=0;if(!chatDraft_.empty()){if(chatDraft_.back()>=0xdc00 && chatDraft_.back()<=0xdfff && chatDraft_.size()>1)chatDraft_.pop_back();chatDraft_.pop_back();}}else if(c>=0xd800 && c<=0xdbff)chatHighSurrogate_=c;else if(c>=0xdc00 && c<=0xdfff){if(chatHighSurrogate_){auto next=chatDraft_;next+=chatHighSurrogate_;next+=c;if(utf8(next).size()<=254)chatDraft_=std::move(next);}chatHighSurrogate_=0;}else{chatHighSurrogate_=0;if(c>=32 && c!=127){auto next=chatDraft_+c;if(utf8(next).size()<=254)chatDraft_=std::move(next);}}}if(input.key==VK_RETURN && !chatDraft_.empty()){if(join_->sendChat(utf8(chatDraft_))){chatDraft_.clear();chatError_.clear();}else chatError_="无法发送聊天消息。";}}auto controls=input;if(chatFocus_ && !screen_.popupOpen())controls.key=0;auto action=screen_.draw("GameChatroom",controls,enabled,true);if(auto change=screen_.takeChoice())changeSlot(*change);screen_.backdropAt("StandardEditBoxBackdropTemplate",edit);screen_.textAt("StandardEditBoxTextTemplate",safeChat(utf8(chatDraft_)),{edit.x+.005f,edit.y,edit.w-.01f,edit.h},state==LanJoinState::Lobby,false,true,.012f);auto& messages=join_->chat();constexpr float line=.014f;auto rows=std::max<size_t>(1,size_t(std::max(0.f,history.h)/line));auto first=messages.size()>rows?messages.size()-rows:0;for(size_t i=first;i<messages.size();++i){auto& entry=messages[i];auto sender=std::find_if(join_->players().begin(),join_->players().end(),[&](const auto& p){return p.id==entry.sender;});auto name=sender==join_->players().end()?"Player "+std::to_string(entry.sender):safeChat(sender->name);auto value=name+": "+safeChat(entry.text);screen_.textAt("StandardInfoTextTemplate",value,{history.x,history.y+float(i-first)*line,history.w,line},true,false,true,.011f);}std::string status;if(!error_.empty())status="连接错误："+display(error_);else if(state==LanJoinState::Connecting)status="正在连接房间…";else if(state==LanJoinState::Joining)status="正在加入房间…";else if(state==LanJoinState::Lobby){switch(mapStatus_){case MapStatus::Waiting:status="已加入房间，等待主机地图信息。";break;case MapStatus::WaitingWorker:status="正在等待地图校验资源。";break;case MapStatus::Checking:status="正在校验本地地图…";break;case MapStatus::Downloading:status="正在接收地图："+std::to_string(join_->mapDownloadBytes())+" / "+std::to_string(expectedMap_?expectedMap_->size:0)+" 字节";break;case MapStatus::WaitingDownloadWorker:status="正在等待地图校验资源。";break;case MapStatus::CheckingDownload:status="正在校验接收的地图…";break;case MapStatus::Matched:status=handoffEnabled_?"本地地图校验一致，等待主机开始对局。":"本地地图校验一致；对局同步尚未实现。";break;case MapStatus::Downloaded:status=handoffEnabled_?"地图接收并校验完成，等待主机开始对局。":"地图接收并校验完成；对局同步尚未实现。";break;case MapStatus::Failed:status="地图校验失败："+display(mapError_);break;}}else if(state==LanJoinState::Rejected)status="主机拒绝加入（"+std::to_string(join_->rejectionCode())+"）";else if(state==LanJoinState::Closed)status="连接已关闭。";else status="连接失败："+display(join_->error());screen_.textAt("StandardInfoTextTemplate",status,{bounds.x,bounds.y+bounds.h+.004f,bounds.w,.024f},true,false,true,.011f);screen_.textAt("StandardInfoTextTemplate",display(game_.mapPath),screen_.bounds("MapInfoPaneContainer"),true,false,true,.011f);if(!chatError_.empty())screen_.textAt("StandardInfoTextTemplate",chatError_,{edit.x,edit.y-.015f,edit.w,.014f},true,false,true,.011f);screen_.overlay();if(action=="CancelButton"){join_->cancel();return action;}return {};
